@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h3>Notepad</h3>

<textarea class="form-control mb-3" rows="12" @bind="content" @bind:event="oninput"
          @ref="textareaRef"></textarea>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private System.Threading.Timer? autoSaveTimer;
    private ElementReference textareaRef;
    private IJSObjectReference? module;

    private const string StorageKeyContent = "notepad-content";
    private const string StorageKeyTimestamp = "notepad-timestamp";

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/notepad-interop.js"
                ?? throw new InvalidOperationException());

            // Restore saved content
            var stored = await JS.InvokeAsync<string?>("localStorage.getItem", StorageKeyContent);
            if (!string.IsNullOrEmpty(stored))
            {
                content = stored;
                savedContent = stored;

                var ts = await JS.InvokeAsync<string?>("localStorage.getItem", StorageKeyTimestamp);
                if (DateTime.TryParse(ts, out var parsed))
                {
                    lastSavedAt = parsed;
                }

                StateHasChanged();
            }

            // Register beforeunload handler
            await module.InvokeVoidAsync("registerBeforeUnload");

            // Start 30-second auto-save timer
            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }

        // Keep JS in sync with whether there are unsaved changes
        if (module is not null)
        {
            await module.InvokeVoidAsync("setUnsaved", HasUnsavedChanges);
        }
    }

    private async Task AutoSaveAsync()
    {
        if (HasUnsavedChanges)
        {
            await PersistAsync();
            StateHasChanged();
        }
    }

    private async Task SaveNowAsync()
    {
        await PersistAsync();
    }

    private async Task PersistAsync()
    {
        await JS.InvokeVoidAsync("localStorage.setItem", StorageKeyContent, content);
        lastSavedAt = DateTime.Now;
        await JS.InvokeVoidAsync("localStorage.setItem", StorageKeyTimestamp,
            lastSavedAt.Value.ToString("o"));
        savedContent = content;

        if (module is not null)
        {
            await module.InvokeVoidAsync("setUnsaved", false);
        }
    }

    private async Task ClearAsync()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        await JS.InvokeVoidAsync("localStorage.removeItem", StorageKeyContent);
        await JS.InvokeVoidAsync("localStorage.removeItem", StorageKeyTimestamp);

        if (module is not null)
        {
            await module.InvokeVoidAsync("setUnsaved", false);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }

        if (module is not null)
        {
            await module.InvokeVoidAsync("unregisterBeforeUnload");
            await module.DisposeAsync();
        }
    }
}

let hasUnsaved = false;

function onBeforeUnload(e) {
    if (hasUnsaved) {
        e.preventDefault();
    }
}

export function registerBeforeUnload() {
    window.addEventListener("beforeunload", onBeforeUnload);
}

export function unregisterBeforeUnload() {
    window.removeEventListener("beforeunload", onBeforeUnload);
}

export function setUnsaved(value) {
    hasUnsaved = value;
}

